# compare known pairs under diagonal, and row reflection r->31-r
D=[]; H=[]
for r in range(30):
 for c in range(30):
  if g[r][c]!=6 and g[c][r]!=6 and g[r][c]!=g[c][r]: D.append((r,c,g[r][c],g[c][r]))
  rr=31-r
  if rr<30 and g[r][c]!=6 and g[rr][c]!=6 and g[r][c]!=g[rr][c]: H.append((r,c,g[r][c],g[rr][c]))
len(D), D[:30],len(H),H[:30]

from collections import deque

def orbit(r,c):
 seen={(r,c)}; q=deque([(r,c)])
 while q:
  i,j=q.popleft()
  candidates=[(j,i)]
  if 2<=i<30: candidates.append((31-i,j))
  for p in candidates:
   if p not in seen and 0<=p[0]<30 and 0<=p[1]<30:
    seen.add(p);q.append(p)
 return seen
hidden=[(r,c) for r in range(30) for c in range(30) if g[r][c]==6]
[(p, len(orbit(*p)), [(q,g[q[0]][q[1]]) for q in orbit(*p) if g[q[0]][q[1]]!=6][:4]) for p in hidden[:20]],len(hidden)

bad=[]
for p in hidden:
 vals={(g[r][c]) for r,c in orbit(*p) if g[r][c]!=6}
 if len(vals)!=1: bad.append((p, vals))
len(bad),bad[:20]

out=[row[:] for row in g]
for r,c in hidden:
 vals={g[i][j] for i,j in orbit(r,c) if g[i][j]!=6}
 assert len(vals)==1
 out[r][c]=vals.pop()
print('\n'.join(' '.join(map(str,row)) for row in out))
